using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides a web search tool that queries the web and returns results.
/// Uses a simple scraping approach via Bing search.
/// </summary>
public sealed class WebSearchTool
{
    private static readonly HttpClient HttpClient = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Searches the web for a given query and returns a list of results with titles, URLs, and snippets.")]
    public static async Task<string> WebSearch(
        [Description("The search query string")] string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            var html = await HttpClient.GetStringAsync(url);
            var results = ParseSearchResults(html);

            if (results.Count == 0)
                return $"No results found for: {query}";

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    private static List<SearchResult> ParseSearchResults(string html)
    {
        var results = new List<SearchResult>();

        // Parse DuckDuckGo HTML results
        var resultBlocks = html.Split("class=\"result__a\"", StringSplitOptions.RemoveEmptyEntries);

        for (var i = 1; i < Math.Min(resultBlocks.Length, 6); i++) // Take top 5 results
        {
            var block = resultBlocks[i];

            var title = ExtractText(block, ">", "</a>");
            var snippet = ExtractSnippet(block);
            var link = ExtractHref(block);

            if (!string.IsNullOrWhiteSpace(title))
            {
                results.Add(new SearchResult
                {
                    Title = WebUtility.HtmlDecode(title).Trim(),
                    Url = link ?? "N/A",
                    Snippet = WebUtility.HtmlDecode(snippet ?? "No snippet available").Trim(),
                });
            }
        }

        return results;
    }

    private static string? ExtractText(string html, string startTag, string endTag)
    {
        var start = html.IndexOf(startTag, StringComparison.Ordinal);
        if (start < 0) return null;
        start += startTag.Length;
        var end = html.IndexOf(endTag, start, StringComparison.Ordinal);
        if (end < 0) return null;
        return StripHtmlTags(html[start..end]);
    }

    private static string? ExtractSnippet(string html)
    {
        var marker = "result__snippet";
        var idx = html.IndexOf(marker, StringComparison.Ordinal);
        if (idx < 0) return null;
        var start = html.IndexOf('>', idx);
        if (start < 0) return null;
        start++;
        var end = html.IndexOf("</", start, StringComparison.Ordinal);
        if (end < 0) return null;
        return StripHtmlTags(html[start..end]);
    }

    private static string? ExtractHref(string html)
    {
        var marker = "result__url";
        var idx = html.IndexOf(marker, StringComparison.Ordinal);
        if (idx < 0) return null;
        var start = html.IndexOf("href=\"", idx, StringComparison.Ordinal);
        if (start < 0) return null;
        start += 6;
        var end = html.IndexOf('"', start);
        if (end < 0) return null;
        var url = html[start..end].Trim();
        if (url.StartsWith("//"))
            url = "https:" + url;
        return WebUtility.UrlDecode(url);
    }

    private static string StripHtmlTags(string input)
    {
        var result = System.Text.RegularExpressions.Regex.Replace(input, "<[^>]+>", "");
        return result.Trim();
    }

    private sealed class SearchResult
    {
        public string Title { get; init; } = "";
        public string Url { get; init; } = "";
        public string Snippet { get; init; } = "";
    }
}

using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking tools for the research agent to collect and review findings.
/// </summary>
public sealed class NotesTool
{
    private readonly List<Note> _notes = [];

    [Description("Saves a research note with a title and content. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("A short title for the note")] string title,
        [Description("The detailed content of the note")] string content,
        [Description("The source URL where this information was found")] string source)
    {
        var note = new Note
        {
            Id = _notes.Count + 1,
            Title = title,
            Content = content,
            Source = source,
            SavedAt = DateTime.UtcNow,
        };

        _notes.Add(note);
        return $"Note #{note.Id} saved: \"{title}\"";
    }

    [Description("Retrieves all saved research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return JsonSerializer.Serialize(_notes, new JsonSerializerOptions { WriteIndented = true });
    }

    public void Clear() => _notes.Clear();

    private sealed class Note
    {
        public int Id { get; init; }
        public string Title { get; init; } = "";
        public string Content { get; init; } = "";
        public string Source { get; init; } = "";
        public DateTime SavedAt { get; init; }
    }
}

