+            Id = _notes.Count + 1,
+            Title = title,
+            Content = content,
+            Source = source,
+            SavedAt = DateTime.UtcNow,
+        };
+
+        _notes.Add(note);
+        return $"Note #{note.Id} saved: \"{title}\"";
+    }
+
+    [Description("Retrieves all saved research notes collected so far.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet.";
+
+        return JsonSerializer.Serialize(_notes, new JsonSerializerOptions { WriteIndented = true });
+    }
+
+    public void Clear() => _notes.Clear();
+
