using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the API key via 'AI:ApiKey' in config or the OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<NotesTool>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notes = host.Services.GetRequiredService<NotesTool>();

// Build AI tool list from the tool classes
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.WebSearch),
    AIFunctionFactory.Create(notes.SaveNote),
    AIFunctionFactory.Create(notes.GetNotes),
};

const string instructions = """
    You are a research assistant. Your goal is to thoroughly research a topic the user provides.

    Follow this process:
    1. Break the topic into 2-3 key search queries.
    2. Use the WebSearch tool to search for information on each query.
    3. Use the SaveNote tool to save important findings as you go.
    4. Use the GetNotes tool to review all your collected notes.
    5. Provide a comprehensive summary of your research to the user.

    Always cite the sources you found. Be thorough but concise.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches a topic by searching the web and taking notes, then summarizes findings.",
    tools: tools);

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notes.Clear();

    Console.WriteLine($"\nResearching: {topic}\n");

    var session = await agent.CreateSessionAsync();

    var runOptions = new ChatClientAgentRunOptions
    {
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        },
    };

    await foreach (var update in agent.RunStreamingAsync(
        $"Research the following topic and provide a detailed summary: {topic}",
        session,
        runOptions))
    {
        if (update.Role == ChatRole.Assistant && !string.IsNullOrEmpty(update.Text))
        {
            Console.Write(update.Text);
        }
    }

    Console.WriteLine("\n");
}

